from pathlib import Path
p=Path(__file__).resolve().parents[1]/'app/src/main/assets/index.html'
s=p.read_text(encoding='utf-8')
if 'living-dex-box-view" content="7.1"' not in s:s=s.replace('</head>','<meta name="living-dex-box-view" content="7.1"/>\n</head>',1)
css=r'''
/* Living Dex Box 7.1 — faithful visual organizer, 30 Pokémon per box. */
.ld71-boxview{display:none;position:fixed;inset:0;z-index:970;background:#f6f8fc;color:#16213b;overflow:auto;padding:calc(16px + env(safe-area-inset-top)) 14px calc(110px + env(safe-area-inset-bottom))}.ld71-boxview.active{display:block}.ld71-head{display:grid;grid-template-columns:auto 1fr auto;gap:12px;align-items:center;max-width:980px;margin:0 auto 14px}.ld71-back{width:44px;height:44px;border:0;border-radius:14px;background:#fff;box-shadow:0 5px 18px rgba(33,48,78,.08);font-size:24px}.ld71-game{display:flex;gap:12px;align-items:center}.ld71-cover{width:72px;height:96px;border-radius:14px;object-fit:cover;box-shadow:0 6px 18px rgba(33,48,78,.12)}.ld71-game h1{margin:0;font-size:24px;line-height:1.05;letter-spacing:-.03em}.ld71-game p{margin:3px 0 0;color:#44516d;font-size:13px}.ld71-progress{display:flex;gap:10px;align-items:center;margin-top:9px;font-weight:900}.ld71-progress small{color:#8d97a9;font-weight:700}.ld71-switch{border:1px solid #dde5f0;background:#fff;border-radius:18px;padding:12px 16px;font-weight:900;color:#132048}.ld71-tabs{max-width:980px;margin:0 auto 14px;display:grid;grid-template-columns:repeat(2,1fr);gap:8px;background:#fff;padding:6px;border-radius:20px;box-shadow:0 6px 18px rgba(33,48,78,.06)}.ld71-tab{border:0;background:transparent;border-radius:15px;min-height:48px;font-weight:900;color:#64708a}.ld71-tab.active{background:#3478e5;color:#fff}.ld71-main{max-width:980px;margin:auto;display:grid;grid-template-columns:190px 1fr;gap:16px}.ld71-boxlist{display:grid;gap:8px;align-content:start;max-height:70vh;overflow:auto;padding-right:2px}.ld71-boxitem{border:0;background:#eef2f8;color:#263553;border-radius:18px;padding:13px 14px;text-align:left;display:grid;grid-template-columns:36px 1fr auto;gap:10px;align-items:center}.ld71-boxitem.active{background:#3478e5;color:#fff}.ld71-boxicon{width:34px;height:34px;border-radius:11px;background:rgba(255,255,255,.65);display:grid;place-items:center}.ld71-boxitem b{display:block;font-size:13px}.ld71-boxitem small{font-size:10px;opacity:.75}.ld71-panel{background:#fff;border:1px solid #e7ecf3;border-radius:24px;padding:16px;box-shadow:0 7px 24px rgba(33,48,78,.06)}.ld71-panelhead{display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:center;margin-bottom:14px}.ld71-panelhead h2{margin:0;font-size:22px}.ld71-count{font-weight:900}.ld71-arrows{display:flex;gap:7px}.ld71-arrow{width:40px;height:40px;border:1px solid #dde5f0;background:#fff;border-radius:12px;font-size:22px}.ld71-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}.ld71-slot{position:relative;border:1px solid #e8edf4;border-radius:16px;background:#f8fafc;min-height:118px;padding:8px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.ld71-slot.registered{background:#f0fbf5}.ld71-slot.missing{background:#f1f3f7}.ld71-num{position:absolute;top:7px;left:8px;font-size:9px;color:#5f6d88}.ld71-slot img{width:68px;height:68px;object-fit:contain}.ld71-slot.missing img{filter:grayscale(1) brightness(.7);opacity:.28}.ld71-name{font-size:10px;font-weight:800;margin-top:2px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ld71-slot.missing .ld71-name{color:#8f98a9}.ld71-footerstats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:14px}.ld71-stat{border:1px solid #e8edf4;background:#fff;border-radius:15px;padding:10px 12px;font-size:10px;display:flex;justify-content:space-between;gap:8px}.ld71-stat b{font-size:12px}.ld71-nav{position:fixed;left:10px;right:10px;bottom:calc(8px + env(safe-area-inset-bottom));z-index:980;display:grid;grid-template-columns:repeat(3,1fr);background:rgba(255,255,255,.97);border:1px solid #e7ecf3;border-radius:24px;padding:7px;box-shadow:0 16px 40px rgba(33,48,78,.15)}.ld71-nav button{border:0;background:transparent;border-radius:17px;min-height:62px;font-weight:850;color:#7d879a}.ld71-nav button.active{background:#eaf2ff;color:#2367d1}
@media(max-width:720px){.ld71-head{grid-template-columns:auto 1fr}.ld71-switch{display:none}.ld71-main{grid-template-columns:1fr}.ld71-boxlist{display:flex;overflow:auto;max-height:none;padding-bottom:4px}.ld71-boxitem{min-width:128px}.ld71-grid{grid-template-columns:repeat(5,minmax(0,1fr))}.ld71-slot{min-height:102px;padding:6px}.ld71-slot img{width:56px;height:56px}.ld71-cover{width:58px;height:78px}.ld71-game h1{font-size:20px}.ld71-panel{padding:12px}.ld71-footerstats{grid-template-columns:1fr}}
@media(max-width:390px){.ld71-grid{grid-template-columns:repeat(5,minmax(0,1fr));gap:5px}.ld71-slot{min-height:86px;border-radius:12px}.ld71-slot img{width:47px;height:47px}.ld71-name{font-size:8px}.ld71-num{font-size:8px}}
'''
s=s.replace('</style>',css+'\n</style>',1)
js=r'''
// Living Dex Box 7.1
let ld71BoxIndex=0;
function ld71Ensure(){if(document.getElementById('ld71BoxView'))return;document.body.insertAdjacentHTML('beforeend','<section id="ld71BoxView" class="ld71-boxview"></section>')}
function ld71Game(){return GAMES.find(g=>g.id===state.activeGameId)||GAMES[0]}
function ld71Dex(){return Array.isArray(currentDex)&&currentGame?.id===state.activeGameId?currentDex:[]}
function ld71RegSet(){
 const ids=new Set();
 const tryObj=o=>{if(!o)return;Object.entries(o).forEach(([k,v])=>{if(v===true||v?.caught||v?.registered||v?.owned)ids.add(Number(k))})};
 tryObj(state?.caught);tryObj(state?.registered);tryObj(state?.owned);tryObj(state?.dex);
 return ids
}
function ld71Name(id){try{const p=(window.DEX_DATA||window.POKEMON_DATA||[]).find?.(x=>Number(x.id)===Number(id));return p?.name||`#${id}`}catch(e){return `#${id}`}}
function ld71Image(id){return `<img src="assets/pokemon/${id}.png" alt="${ld71Name(id)}">`}
function ld71BoxCount(){const n=ld71Dex().length||0;return Math.max(1,Math.ceil(n/30))}
function ld71Open(){ld71Ensure();document.body.classList.remove('game-dex-focus');const e=document.getElementById('ld71BoxView');e.classList.add('active');ld71Render()}
function ld71Close(){document.getElementById('ld71BoxView')?.classList.remove('active');ld7Home?.()}
function ld71OpenDex(){document.getElementById('ld71BoxView')?.classList.remove('active');ld7OpenCurrent?.()}
function ld71SetBox(i){ld71BoxIndex=Math.max(0,Math.min(ld71BoxCount()-1,i));ld71Render()}
function ld71Toggle(id){
 // Reuse the existing Living Dex click path when possible, so Box and Dex stay synchronized.
 const el=[...document.querySelectorAll('#dexGrid .pk,[data-id]')].find(x=>Number(x.dataset?.id||x.getAttribute('data-id'))===Number(id));
 if(el){el.click();setTimeout(ld71Render,80);return}
 if(typeof toggleCaught==='function'){toggleCaught(id);setTimeout(ld71Render,80);return}
 if(state.caught){state.caught[id]=!state.caught[id];try{saveState?.()}catch(e){}ld71Render()}
}
function ld71Render(){
 const root=document.getElementById('ld71BoxView');if(!root)return;const g=ld71Game(),dex=ld71Dex(),regs=ld71RegSet(),total=dex.length||0,done=dex.filter(x=>regs.has(Number(x.id||x))).length,pct=total?Math.round(done/total*100):0,boxes=ld71BoxCount();
 if(ld71BoxIndex>=boxes)ld71BoxIndex=boxes-1;const start=ld71BoxIndex*30,end=Math.min(start+30,total),slice=dex.slice(start,end);while(slice.length<30&&start+slice.length<total)slice.push(dex[start+slice.length]);
 const boxDone=slice.filter(x=>regs.has(Number(x.id||x))).length;
 const cover=(()=>{const map={sv:'sv.jpg',za:'za.jpg',swsh:'swsh.jpg',bdsp:'bdsp.jpg',letsgo:'letsgo.jpg',arceus:'arceus.jpg'};return `assets/ui45/${map[g.id]||'sv.jpg'}`})();
 root.innerHTML=`<div class="ld71-head"><button class="ld71-back" onclick="ld71Close()">‹</button><div class="ld71-game"><img class="ld71-cover" src="${cover}"><div><h1>${g.name}</h1><p>Living Dex</p><div class="ld71-progress"><span>${done} / ${total}</span><small>${pct}%</small></div></div></div><button class="ld71-switch" onclick="ld7Library()">Trocar jogo</button></div><div class="ld71-tabs"><button class="ld71-tab" onclick="ld71OpenDex()">Pokédex</button><button class="ld71-tab active">Box</button></div><div class="ld71-main"><aside class="ld71-boxlist">${Array.from({length:boxes},(_,i)=>{const bs=i*30,be=Math.min(bs+30,total),cnt=dex.slice(bs,be).filter(x=>regs.has(Number(x.id||x))).length;return `<button class="ld71-boxitem ${i===ld71BoxIndex?'active':''}" onclick="ld71SetBox(${i})"><span class="ld71-boxicon">▣</span><span><b>Box ${i+1}</b><small>${cnt} / ${be-bs}</small></span><span>›</span></button>`}).join('')}</aside><section class="ld71-panel"><div class="ld71-panelhead"><h2>Box ${ld71BoxIndex+1}</h2><span class="ld71-count">${boxDone} / ${slice.length}</span><div class="ld71-arrows"><button class="ld71-arrow" onclick="ld71SetBox(${ld71BoxIndex-1})">‹</button><button class="ld71-arrow" onclick="ld71SetBox(${ld71BoxIndex+1})">›</button></div></div><div class="ld71-grid">${slice.map((x,i)=>{const id=Number(x.id||x),ok=regs.has(id);return `<button class="ld71-slot ${ok?'registered':'missing'}" onclick="ld71Toggle(${id})"><span class="ld71-num">${String(start+i+1).padStart(3,'0')}</span>${ld71Image(id)}<span class="ld71-name">${ld71Name(id)}</span></button>`}).join('')}</div><div class="ld71-footerstats"><div class="ld71-stat"><span>Registrado</span><b>${boxDone}</b></div><div class="ld71-stat"><span>Não registrado</span><b>${slice.length-boxDone}</b></div><div class="ld71-stat"><span>Total na box</span><b>${slice.length}</b></div></div></section></div><nav class="ld71-nav"><button onclick="ld7Home()">Início</button><button onclick="ld7Library()">Biblioteca</button><button class="active">Box</button></nav>`
}
// Extend Living Dex-only nav with Box as a first-class destination.
const ld71OldNav=window.ld7Nav;window.ld7Nav=function(){const nav=document.querySelector('.mnav');if(!nav)return;nav.innerHTML=`<button class="ld7-navbtn" data-ld7="home" onclick="ld7Home()"><span>Início</span></button><button class="ld7-navbtn" data-ld7="games" onclick="ld7Library()"><span>Biblioteca</span></button><button class="ld7-navbtn" data-ld7="dex" onclick="ld7OpenCurrent()"><span>Living Dex</span></button><button class="ld7-navbtn" data-ld7="box" onclick="ld71Open()"><span>Box</span></button>`;nav.style.gridTemplateColumns='repeat(4,1fr)';ld7NavState?.()}
const ld71OldState=window.ld7NavState;window.ld7NavState=function(){if(typeof ld71OldState==='function')ld71OldState();if(document.getElementById('ld71BoxView')?.classList.contains('active')){document.querySelectorAll('.ld7-navbtn').forEach(b=>b.classList.remove('active'));document.querySelector('.ld7-navbtn[data-ld7="box"]')?.classList.add('active')}}
ld71Ensure();setTimeout(()=>{try{ld7Nav()}catch(e){}},150)
'''
s=s.replace('</body>','<script>'+js+'</script>\n</body>',1)
p.write_text(s,encoding='utf-8')
print('Living Dex Box 7.1 applied')